def solve(operations):
    class Account:
        def __init__(self): self.balance = 0
        def apply(self, operation, amount):
            if operation == 'deposit':
                self.balance += amount
                return True
            if amount > self.balance: return False
            self.balance -= amount
            return True
    account = Account()
    accepted = [account.apply(operation,amount) for operation,amount in operations]
    return {'balance':account.balance,'accepted':accepted}
